// Historical time-zone conversion from the generated IANA transition table (design.md 10.1 F4, plan.md P10).
// Never consults Intl or the device offset, so Node, Hermes and browsers agree to the second.
// Table: data/tz-transitions.json, generated by scripts/build-tz-table.ts (tzdb release in `header.tzdb`).
import tableJson from '../../data/tz-transitions.json';
import { monthNames, monthShort, pad2, weekdayNames, weekdayShort, type Lang } from '../locale/index';

export interface ZoneTable {
  /** UTC seconds at which period i ends; offsets[i] applies while utc < untils[i]. */
  untils: number[];
  /** Minutes east of UTC; offsets.length === untils.length + 1. */
  offsets: number[];
}

export interface TzTable {
  header: { tzdb: string; generated: string; range: [number, number]; zoneCount: number; linkCount: number };
  zones: Record<string, ZoneTable>;
  links: Record<string, string>;
}

const table = tableJson as unknown as TzTable;

/** tzdb release the bundled table was generated from (e.g. "2026e"). */
export const TZDB_VERSION: string = table.header.tzdb;

const ZONE_LIST: readonly string[] = Object.keys(table.zones).sort();
const ZONE_INDEX = new Map<string, number>(ZONE_LIST.map((z, i) => [z, i]));

/**
 * Maps any tzdb name (canonical or link such as Asia/Calcutta, Europe/Kiev, US/Eastern) to the canonical
 * id used as a table key. Returns undefined for names the table does not know.
 */
export function canonicalZone(name: string): string | undefined {
  if (!name) return undefined;
  const trimmed = name.trim();
  if (table.zones[trimmed]) return trimmed;
  const linked = table.links[trimmed];
  if (linked && table.zones[linked]) return linked;
  // Case-insensitive fallback for hand-typed ids (asia/kolkata).
  const lower = trimmed.toLowerCase();
  for (const z of ZONE_LIST) if (z.toLowerCase() === lower) return z;
  for (const alias of Object.keys(table.links)) if (alias.toLowerCase() === lower) return table.links[alias];
  return undefined;
}

export function hasZone(name: string): boolean {
  return canonicalZone(name) !== undefined;
}

/** Sorted canonical zone ids (stable for a given table; used by share-codes via zoneIndex/zoneAt). */
export function zoneList(): readonly string[] {
  return ZONE_LIST;
}

/** Index of a zone (after canonicalisation) in the sorted list, or -1 when unknown. */
export function zoneIndex(zone: string): number {
  const canonical = canonicalZone(zone);
  if (!canonical) return -1;
  return ZONE_INDEX.get(canonical) ?? -1;
}

export function zoneAt(index: number): string | undefined {
  return ZONE_LIST[index];
}

function zoneTable(zone: string): ZoneTable {
  const canonical = canonicalZone(zone);
  if (!canonical) throw new Error(`Unknown time zone: ${zone}`);
  return table.zones[canonical];
}

/** Offset in minutes east of UTC in force at the given UTC instant (ms since the Unix epoch). */
export function offsetAt(zone: string, utcMs: number): number {
  const z = zoneTable(zone);
  const t = utcMs / 1000;
  // Binary search for the first until > t.
  let lo = 0;
  let hi = z.untils.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (z.untils[mid] > t) hi = mid;
    else lo = mid + 1;
  }
  return z.offsets[lo];
}

export interface WallTime {
  y: number;
  m: number; // 1-12
  d: number; // 1-31
  hh: number; // 0-23
  mm: number; // 0-59
  ss?: number; // 0-59
}

export interface LocalToUtcResult {
  utcMs: number;
  /** Minutes east of UTC that were applied. */
  offsetMinutes: number;
  /** The wall time fell in a gap (clock moved forward); it was shifted forward across the gap. */
  clockGap: boolean;
  /** The wall time occurred twice (clock moved back); the earlier instant was used. */
  overlap: boolean;
}

const DAY_MS = 86_400_000;

function wallToPseudoUtcMs(w: WallTime): number {
  return Date.UTC(w.y, w.m - 1, w.d, w.hh, w.mm, w.ss ?? 0);
}

/**
 * Converts a wall-clock time in a zone to a UTC instant.
 * Gap (spring forward): the wall time does not exist; the result is the instant obtained by applying the
 * pre-transition offset, which lands after the transition (the clock reads wall + gap), and clockGap=true.
 * Overlap (fall back): the wall time exists twice; the earlier instant is returned and overlap=true.
 */
export function localToUtc(zone: string, wall: WallTime): LocalToUtcResult {
  const pseudo = wallToPseudoUtcMs(wall);
  const offBefore = offsetAt(zone, pseudo - DAY_MS);
  const offAfter = offsetAt(zone, pseudo + DAY_MS);
  const candidates = offBefore === offAfter ? [offBefore] : [offBefore, offAfter];
  const valid: { utcMs: number; offset: number }[] = [];
  for (const off of candidates) {
    const utcMs = pseudo - off * 60_000;
    if (offsetAt(zone, utcMs) === off) valid.push({ utcMs, offset: off });
  }
  if (valid.length === 1) {
    return { utcMs: valid[0].utcMs, offsetMinutes: valid[0].offset, clockGap: false, overlap: false };
  }
  if (valid.length > 1) {
    valid.sort((a, b) => a.utcMs - b.utcMs);
    return { utcMs: valid[0].utcMs, offsetMinutes: valid[0].offset, clockGap: false, overlap: true };
  }
  // Gap: apply the offset in force before the transition; the instant lands after the transition.
  const utcMs = pseudo - offBefore * 60_000;
  return { utcMs, offsetMinutes: offsetAt(zone, utcMs), clockGap: true, overlap: false };
}

export interface ZonedWallTime extends Required<WallTime> {
  /** 0 = Sunday. */
  weekday: number;
  offsetMinutes: number;
}

/** Breaks a UTC instant into the wall-clock fields of the zone. */
export function utcToWall(utcMs: number, zone: string): ZonedWallTime {
  const off = offsetAt(zone, utcMs);
  const local = new Date(utcMs + off * 60_000);
  return {
    y: local.getUTCFullYear(),
    m: local.getUTCMonth() + 1,
    d: local.getUTCDate(),
    hh: local.getUTCHours(),
    mm: local.getUTCMinutes(),
    ss: local.getUTCSeconds(),
    weekday: local.getUTCDay(),
    offsetMinutes: off,
  };
}

/** "+05:30" style label for an offset in minutes east (seconds shown only when non-zero). */
export function formatOffset(offsetMinutes: number): string {
  const sign = offsetMinutes < 0 ? '-' : '+';
  const totalSeconds = Math.round(Math.abs(offsetMinutes) * 60);
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  return `${sign}${pad2(h)}:${pad2(m)}${s ? `:${pad2(s)}` : ''}`;
}

/**
 * Formats a UTC instant in a zone with a small pattern language (Latin digits, tabular-friendly):
 *   yyyy yy | MMMM MMM MM M | dd d | EEEE EEE | HH H | mm | ss | 'literal'
 * Example: formatInZone(t, 'Asia/Kolkata', 'EEE d MMM yyyy · HH:mm', 'hi') -> "गुरु 22 अक्टू 2026 · 06:27".
 */
export function formatInZone(utcMs: number, zone: string, pattern: string, lang: Lang = 'en'): string {
  const w = utcToWall(utcMs, zone);
  let out = '';
  let i = 0;
  while (i < pattern.length) {
    const ch = pattern[i];
    if (ch === "'") {
      const end = pattern.indexOf("'", i + 1);
      if (end === -1) {
        out += pattern.slice(i + 1);
        break;
      }
      out += pattern.slice(i + 1, end);
      i = end + 1;
      continue;
    }
    if (!/[yMdEHms]/.test(ch)) {
      out += ch;
      i++;
      continue;
    }
    let j = i;
    while (j < pattern.length && pattern[j] === ch) j++;
    const token = pattern.slice(i, j);
    switch (token) {
      case 'yyyy':
        out += String(w.y);
        break;
      case 'yy':
        out += pad2(w.y % 100);
        break;
      case 'MMMM':
        out += monthNames[lang][w.m - 1];
        break;
      case 'MMM':
        out += monthShort[lang][w.m - 1];
        break;
      case 'MM':
        out += pad2(w.m);
        break;
      case 'M':
        out += String(w.m);
        break;
      case 'dd':
        out += pad2(w.d);
        break;
      case 'd':
        out += String(w.d);
        break;
      case 'EEEE':
        out += weekdayNames[lang][w.weekday];
        break;
      case 'EEE':
        out += weekdayShort[lang][w.weekday];
        break;
      case 'HH':
        out += pad2(w.hh);
        break;
      case 'H':
        out += String(w.hh);
        break;
      case 'mm':
        out += pad2(w.mm);
        break;
      case 'ss':
        out += pad2(w.ss);
        break;
      default:
        out += token;
    }
    i = j;
  }
  return out;
}
